import time, random, string
def lev(a,b):
    if a==b: return 0
    la,lb=len(a),len(b)
    if la==0: return lb
    if lb==0: return la
    prev=list(range(lb+1))
    for i in range(1,la+1):
        cur=[i]+[0]*lb; ca=a[i-1]
        for j in range(1,lb+1):
            cur[j]=min(prev[j]+1, cur[j-1]+1, prev[j-1]+(ca!=b[j-1]))
        prev=cur
    return prev[lb]
random.seed(0)
def rs(n): return ''.join(random.choice(string.ascii_letters+' ') for _ in range(n))
pairs=[(rs(12),rs(12)),(rs(40),rs(40)),(rs(200),rs(200)),(rs(1000),rs(1000))]
for a,b in pairs:
    t=time.perf_counter()
    N=2000 if len(a)<=40 else (500 if len(a)<=200 else 20)
    for _ in range(N): lev(a,b)
    dt=(time.perf_counter()-t)/N
