import time,random,string
def lev_banded(a,b,k):
    # returns min(ED, k+1); early-abandon. Work is O(len(a)*(2k+1))
    la,lb=len(a),len(b)
    if abs(la-lb)>k: return k+1
    INF=k+1
    prev=[j if j<=k else INF for j in range(lb+1)]
    for i in range(1,la+1):
        cur=[i if i<=k else INF]+[INF]*lb; ca=a[i-1]; lo=max(1,i-k); hi=min(lb,i+k)
        left=INF
        for j in range(1,lb+1):
            if j<lo or j>hi: cur[j]=INF; left=INF; continue
            cost=0 if ca==b[j-1] else 1
            cur[j]=min(prev[j]+1, left+1, prev[j-1]+cost)
            left=cur[j]
        if min(cur)>k: return INF
        prev=cur
    return prev[lb] if prev[lb]<=k else INF
random.seed(1)
def rs(n): return ''.join(random.choice(string.ascii_letters) for _ in range(n))
for L in [40,200,1000]:
    a,b=rs(L), rs(L-1)
    for k in [1,2,3]:
        t=time.perf_counter(); N=500 if L<=200 else 50
        for _ in range(N): lev_banded(a,b,k)
        dt=(time.perf_counter()-t)/N
        print(f"len={L:5d} band k={k}: {dt*1e6:9.1f} us  -> {1/dt:9,.0f}/s")
